using System;
using System.Collections.Generic;
using UnityEngine;
public sealed class CapybaraAppearanceApplier : MonoBehaviour { [Serializable] private sealed class MaterialSlot { [SerializeField] private CapybaraColorSlot slot; [SerializeField] private Renderer renderer; [SerializeField] private int materialIndex; public CapybaraColorSlot Slot => slot; public Renderer Renderer => renderer; public int MaterialIndex => materialIndex; } [SerializeField] private MaterialSlot[] materialSlots = Array.Empty<MaterialSlot>(); [SerializeField] private CapybaraEyeController eyes; [SerializeField] private HeadAccessoryApplier headAccessory; private readonly Dictionary<Renderer, MaterialPropertyBlock> blocks = new(); public PlayerCosmeticLoadout AppliedLoadout { get; private set; } = new(); public void Apply(PlayerCosmeticLoadout loadout, CosmeticCatalog catalog) { AppliedLoadout = loadout ?? new PlayerCosmeticLoadout(); foreach (MaterialSlot item in materialSlots) { if (item == null || item.Renderer == null || item.MaterialIndex < 0 || item.MaterialIndex >= item.Renderer.sharedMaterials.Length) continue; Material material = item.Renderer.sharedMaterials[item.MaterialIndex]; if (material == null) continue; Color baseColor = material.HasProperty("_BaseColor") ? material.GetColor("_BaseColor") : material.HasProperty("_Color") ? material.GetColor("_Color") : Color.white; CapybaraColorSelection choice = AppliedLoadout.Get(item.Slot); Color.RGBToHSV(baseColor, out _, out _, out float value); Color color = Color.HSVToRGB(Mathf.Repeat(choice.Hue, 1f), Mathf.Clamp01(choice.Saturation), Mathf.Max(.02f, value)); if (!blocks.TryGetValue(item.Renderer, out MaterialPropertyBlock block)) { block = new MaterialPropertyBlock(); blocks.Add(item.Renderer, block); } item.Renderer.GetPropertyBlock(block, item.MaterialIndex); if (material.HasProperty("_BaseColor")) block.SetColor("_BaseColor", color); else if (material.HasProperty("_Color")) block.SetColor("_Color", color); item.Renderer.SetPropertyBlock(block, item.MaterialIndex); } if (catalog != null) { eyes?.SetExpression(catalog.FindExpression(AppliedLoadout.expressionId) ?? catalog.DefaultExpression); headAccessory?.SetAccessory(catalog.FindHeadAccessory(AppliedLoadout.headAccessoryId)); } } }
